final void Function(Duration target) onSeek;

/// Optional seek feedback during scrubbing (called on drag start/update).
/// Parent can render it in the UI (e.g. Void's bottom crumb line).
final void Function(int positionMs, int durationMs, double progress)?
    onSeekFeedbackUpdate;

/// Optional callback after scrubbing ends.
final void Function()? onSeekFeedbackEnd;

edits.oldText:
void onSeekStart(DragStartDetails _) {
  seekStartMs.value = positionMs();
  seekDurationMs.value = durationMs();
  seekAccumDx.value = 0;
  seekTargetMs.value = seekStartMs.value;
  seeking.value = true;
}

edits.newText:
void onSeekStart(DragStartDetails _) {
  seekStartMs.value = positionMs();
  seekDurationMs.value = durationMs();
  seekAccumDx.value = 0;
  seekTargetMs.value = seekStartMs.value;
  seeking.value = true;

  onSeekFeedbackUpdate?.call(
    seekTargetMs.value,
    seekDurationMs.value,
    seekDurationMs.value <= 0
        ? 0.0
        : (seekTargetMs.value / seekDurationMs.value).clamp(0.0, 1.0),
  );
}

edits.oldText:
void onSeekUpdate(DragUpdateDetails d) {
  if (seekDurationMs.value <= 0) return;
  seekAccumDx.value += d.primaryDelta ?? 0;
  final raw = seekStartMs.value +
      (seekAccumDx.value / width.value) * seekDurationMs.value;
  seekTargetMs.value =
      raw.clamp(0, seekDurationMs.value.toDouble()).round();
}

